require_relative 'hashing'
require_relative 'transactions'

module Ledger
  class Block
    attr_reader :height, :previous, :root, :timestamp, :difficulty, :nonce, :transactions, :id, :size

    def initialize(height, previous, root, timestamp, difficulty, nonce, transactions)
      @height = height
      @previous = previous
      @root = root
      @timestamp = timestamp
      @difficulty = difficulty
      @nonce = nonce
      @transactions = transactions
      @id = Hashing.digest(header)
      @size = transactions.drop(1).sum(&:size)
    end

    def header
      [@height, @previous, @root, @timestamp, @difficulty, @nonce].join('|')
    end

    def proof_of_work?
      @id.start_with?('0' * @difficulty)
    end

    def self.parse(fields, transaction_lines)
      height, previous, root, timestamp, difficulty, nonce = fields
      new(height.to_i, previous, root, timestamp.to_i, difficulty.to_i, nonce.to_i,
          transaction_lines.map { |line| Transaction.new(line) })
    end

    def self.mine(height, previous, timestamp, difficulty, transactions)
      root = Hashing.merkle(transactions.map(&:txid))
      nonce = 0
      loop do
        block = new(height, previous, root, timestamp, difficulty, nonce, transactions)
        return block if block.proof_of_work?

        nonce += 1
      end
    end

    def context_error(maximum_size)
      return 'bad-pow' unless proof_of_work?
      return 'bad-merkle' unless Hashing.merkle(@transactions.map(&:txid)) == @root
      if !@transactions.first.coinbase? || @transactions.first.coinbase_height != @height ||
         @transactions.drop(1).any?(&:coinbase?)
        return 'bad-structure'
      end
      return 'too-large' if @size > maximum_size

      nil
    end
  end
end

require_relative 'hashing'
require_relative 'wallets'

module Ledger
  Coin = Struct.new(:address, :amount, :height, :coinbase) do
    def mature?(height, maturity)
      !coinbase || self.height.zero? || height >= self.height + maturity
    end
  end

  class Transaction
    attr_reader :text, :txid, :size, :body, :inputs, :outputs, :signatures, :coinbase_height

    def initialize(text)
      @text = text
      @txid = Hashing.digest(text)
      @size = text.bytesize
      parts = text.split(';')
      @outputs = parts[1].delete_prefix('out=').split(',').map do |output|
        address, amount = output.split(':')
        [address, amount.to_i]
      end
      if text.start_with?('cb=')
        @coinbase_height = parts[0].delete_prefix('cb=').to_i
        @inputs = []
        @signatures = []
        @body = nil
      else
        @coinbase_height = nil
        @inputs = parts[0].delete_prefix('in=').split(',').map do |input|
          txid, index = input.split(':')
          [txid, index.to_i]
        end
        @signatures = parts[2].delete_prefix('sig=').split(',')
        @body = text.split(';sig=', 2).first
      end
    end

    def coinbase?
      !@coinbase_height.nil?
    end

    def self.create(inputs, outputs, secret)
      body = "in=#{inputs.map { |reference| reference.join(':') }.join(',')};out=#{outputs.map { |output| output.join(':') }.join(',')}"
      signatures = inputs.each_index.map { |index| Wallets.signature(secret, index, body) }
      new("#{body};sig=#{signatures.join(',')}")
    end

    def self.coinbase(height, outputs)
      new("cb=#{height};out=#{outputs.map { |output| output.join(':') }.join(',')}")
    end

    def bad_outputs?(wallets)
      @outputs.any? { |address, amount| wallets.owner(address).nil? || amount.zero? }
    end

    def output_amount
      @outputs.sum { |_, amount| amount }
    end

    def check(utxo, spent, height, wallets, maturity)
      return ['bad-output'] if bad_outputs?(wallets)

      seen = {}
      input_amount = 0
      @inputs.each_with_index do |reference, index|
        return ['double-spend'] if spent[reference] || seen[reference]

        seen[reference] = true
        coin = utxo[reference]
        return ['missing-input'] unless coin
        return ['immature'] unless coin.mature?(height, maturity)

        secret = wallets.owner(coin.address).secret
        return ['bad-sig'] unless @signatures[index] == Wallets.signature(secret, index, @body)

        input_amount += coin.amount
      end
      output_amount = self.output_amount
      return ['overspend'] if input_amount < output_amount

      [nil, input_amount - output_amount]
    end

    def apply(utxo, height)
      @inputs.each { |reference| utxo.delete(reference) }
      @outputs.each_with_index do |(address, amount), index|
        utxo[[@txid, index]] = Coin.new(address, amount, height, coinbase?)
      end
      utxo
    end
  end
end

require_relative 'hashing'

module Ledger
  Wallet = Struct.new(:name, :secret, :address)

  class Wallets
    attr_reader :all

    def initialize(path)
      @all = File.readlines(path, chomp: true).map do |line|
        name, secret = line.split
        Wallet.new(name, secret, Hashing.digest("addr:#{secret}")[0, 16])
      end
      @by_name = @all.to_h { |wallet| [wallet.name, wallet] }
      @by_address = @all.to_h { |wallet| [wallet.address, wallet] }
    end

    def [](name)
      @by_name.fetch(name)
    end

    def owner(address)
      @by_address[address]
    end

    def self.signature(secret, index, body)
      Hashing.digest("#{secret}:#{index}:#{body}")[0, 16]
    end
  end
end
